import{_ as o,C as a,o as l,c as d,a2 as t,j as r,G as i}from"./chunks/framework.BgSoyxN5.js";const _=JSON.parse('{"title":"Fear & Greed: The Direction, Not Just The Level | TickerForge","description":"A sentiment number on its own is ambiguous — 30 on the way up and 30 on the way down are opposite situations. TickerForge publishes the direction sentiment is moving in, daily, and flags the days it turns.","frontmatter":{"title":"Fear & Greed: The Direction, Not Just The Level | TickerForge","description":"A sentiment number on its own is ambiguous — 30 on the way up and 30 on the way down are opposite situations. TickerForge publishes the direction sentiment is moving in, daily, and flags the days it turns.","aside":false,"locale":"en","alternateLocales":{"en":"/market-intelligence/fear-and-greed","ru":"/ru/market-intelligence/fear-and-greed"},"pageClass":"partners-page"},"headers":[],"relativePath":"market-intelligence/fear-and-greed.md","filePath":"market-intelligence/fear-and-greed.md","lastUpdated":1788182993000}'),h={name:"market-intelligence/fear-and-greed.md"},c={class:"partners-wide"},p={class:"partners-post-gallery"};function m(g,e,u,f,k,T){const n=a("PartnerPostImage"),s=a("PartnerChannelCta");return l(),d("div",null,[e[0]||(e[0]=t('<h1 id="fear-amp-greed" tabindex="-1">Fear &amp; Greed <a class="header-anchor" href="#fear-amp-greed" aria-label="Permalink to &quot;Fear &amp;amp; Greed&quot;">​</a></h1><p>Everyone publishes the level. The level alone is the least useful half of the reading.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="https://t.me/TickerForgeBot?start=src_channel_fear_greed" rel="nofollow">Open the Fear &amp; Greed card</a><a class="partners-button partners-button--secondary" href="#publish">Publish it in your channel</a></div><p class="partners-locale-switch"><a href="/ru/market-intelligence/fear-and-greed" hreflang="ru">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/market-intelligence/">All market intelligence reads</a> · <a href="/market-intelligence/market-stress">Market Stress</a> · <a href="/market-intelligence/market-regime">Market Regime</a></p><h2 id="answers" tabindex="-1">The Question It Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;The Question It Answers {#answers}&quot;">​</a></h2><p><strong>&quot;Is sentiment recovering or still deteriorating?&quot;</strong></p><p>A reading of 30 reached on the way down from 60 and a reading of 30 reached on the way up from 10 are opposite situations. They print the same number. Every feed that republishes &quot;Fear &amp; Greed: 30&quot; hands a reader a figure that cannot be acted on without the piece that was dropped.</p><h2 id="why" tabindex="-1">Why This Read Is Different <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why This Read Is Different {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>The direction is computed, not eyeballed.</strong> TickerForge runs trend logic on the sentiment index itself — moving averages and relative strength on the series — and publishes where it is heading alongside where it is.</li><li><strong>The artwork carries the direction, the text carries the level.</strong> That is deliberate: the direction is the part a reader cannot get anywhere else, so it is the part that survives being seen in a scrolling feed.</li><li><strong>Turns get their own alert.</strong> The day sentiment direction flips is a different event from a day it merely continued, and it is published as one.</li><li><strong>It is one line in a bigger picture.</strong> Sentiment is not a strategy on its own. It is most useful read against <a href="/market-intelligence/market-regime">the market regime</a> and <a href="/market-intelligence/market-stress">market stress</a> — improving sentiment inside a Defensive regime means something different from the same reading inside a Trend one.</li></ul></div><h2 id="example" tabindex="-1">What The Post Looks Like <a class="header-anchor" href="#example" aria-label="Permalink to &quot;What The Post Looks Like {#example}&quot;">​</a></h2>',11)),r("div",c,[r("div",p,[i(n,{src:"/partners/examples/fear-and-greed-sample.png",alt:"TickerForge Fear and Greed post: the sentiment level with the gauge showing which direction it is moving",caption:"The level in the text, the direction on the gauge."})])]),e[1]||(e[1]=t('<h2 id="method" tabindex="-1">How It Is Built <a class="header-anchor" href="#method" aria-label="Permalink to &quot;How It Is Built {#method}&quot;">​</a></h2><p>The sentiment index is tracked as a series, and the direction is derived from that series with the same trend logic TickerForge applies elsewhere — short and long moving averages plus relative strength — rather than from a day-over-day difference, which flips on noise.</p><h2 id="publish" tabindex="-1">Two Ways To Use It <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Two Ways To Use It {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Read it.</strong> The daily post runs on the TickerForge public channel; the card with the current level and direction is in the bot.</li><li><strong>Publish it.</strong> Fear &amp; Greed is available for partner pilots — tell us it is the format your channel needs on the <a href="/partners/market-news">Market News</a> page and we prioritise by what partners actually ask for.</li></ul></div>',4)),i(s),e[2]||(e[2]=t('<p>Sentiment is context, not a signal. A fearful market is not automatically a buying opportunity and a greedy one is not automatically a top. TickerForge is educational decision-support software, not financial advice.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/market-intelligence/">All market intelligence reads</a></li><li><a href="/market-intelligence/market-regime">Market Regime</a></li><li><a href="/market-intelligence/market-stress">Market Stress</a></li><li><a href="/partners/market-news">Market news partner program</a></li></ul>',3))])}const b=o(h,[["render",m]]);export{_ as __pageData,b as default};
